@startuml

class User {
  + Id : string
}

class Doctor extends User {
  + FirstName : string
  + LastName : string
}

class Patient extends User {
  + Age : int
  + Address : string
}

class Hospital {
}

class Office {
}

class Schedule {
  + StartDate : date
  + StartTime : time
  + EndTime : time
}

class Appointment {
  + Id : string
  + Date : date
  + StartTime : time
  + EndTime : time
}

class BloodTest extends Appointment {}

class Consultation extends Appointment {}

class Surgery extends Appointment {}

Hospital "1" *-- "*" Office
Doctor "1" -- "*" Office : applies to
Doctor "1" -- "*" Schedule : creates
Office "1" -- "*" Schedule
Patient "1" -- "*" Appointment : books
Doctor "1" -- "*" Appointment : attends
Schedule "1" -- "0..*" Appointment : for
Appointment ..> User : email sent to

@enduml

